CREATE OR REPLACE FUNCTION app.enqueue_notification(p_tenant uuid, p_customer uuid, p_kind text, p_channels text[], p_payload jsonb, p_dedupe text DEFAULT NULL::text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_ch text;
  v_n int := 0;
  v_marketing boolean := p_kind in ('offer', 'news_promo');
  v_phone text;
begin
  select phone into v_phone from public.customers where id = p_customer;
  foreach v_ch in array p_channels loop
    if v_ch <> 'inapp' and v_marketing and not app.has_marketing_consent(p_customer, v_ch) then continue; end if;
    if not app.pref_enabled(p_customer, case when p_kind = 'news_promo' then 'offer' else p_kind end, v_ch) then continue; end if;
    if v_ch = 'sms' and v_phone is null then continue; end if;
    insert into public.notification_queue (tenant_id, customer_id, channel, kind, payload, dedupe_key)
    values (p_tenant, p_customer, v_ch, p_kind, p_payload, case when p_dedupe is null then null else p_dedupe || ':' || v_ch end)
    on conflict (dedupe_key) do nothing;
    v_n := v_n + 1;
  end loop;
  return v_n;
end
$function$

CREATE OR REPLACE FUNCTION app.new_customer_number(p_tenant uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_chars constant text := '23456789ABCDEFGHJKLMNPQRSTUVWXYZ';
  v_bytes bytea;
  v_num text;
  i int;
begin
  loop
    v_bytes := extensions.gen_random_bytes(6);
    v_num := 'HB-';
    for i in 0..5 loop
      v_num := v_num || substr(v_chars, (get_byte(v_bytes, i) % 32) + 1, 1);
    end loop;
    exit when not exists (select 1 from public.customers where tenant_id = p_tenant and customer_number = v_num);
  end loop;
  return v_num;
end
$function$

CREATE OR REPLACE FUNCTION app.slot_ok(p_tenant uuid, p_staff uuid, p_start timestamp with time zone, p_end timestamp with time zone, p_ignore uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_tz text;
  v_ls timestamp;
  v_le timestamp;
  v_dow int;
  v_oh public.opening_hours;
  v_sh public.staff_hours;
begin
  select time_zone into v_tz from public.tenants where id = p_tenant;
  v_ls := p_start at time zone v_tz;
  v_le := p_end at time zone v_tz;
  if v_ls::date <> v_le::date then
    return false;
  end if;
  v_dow := extract(dow from v_ls);

  select * into v_oh from public.opening_hours where tenant_id = p_tenant and weekday = v_dow;
  if not found or v_ls::time < v_oh.opens or v_le::time > v_oh.closes then
    return false;
  end if;

  if exists (select 1 from public.staff_hours h where h.staff_id = p_staff) then
    select * into v_sh from public.staff_hours h where h.staff_id = p_staff and h.weekday = v_dow;
    if not found or v_ls::time < v_sh.starts or v_le::time > v_sh.ends then
      return false;
    end if;
  end if;

  return not exists (
    select 1 from public.appointments a
    where a.staff_id = p_staff
      and a.status in ('pending', 'confirmed')
      and tstzrange(a.starts_at, a.ends_at, '[)') && tstzrange(p_start, p_end, '[)')
      and (p_ignore is null or a.id <> p_ignore));
end
$function$

CREATE OR REPLACE FUNCTION public.available_slots(p_service_id uuid, p_staff_id uuid, p_date date)
 RETURNS TABLE(start text, staff_id uuid)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
#variable_conflict use_column
declare
  v_tenant uuid := app.current_tenant();
  v_t public.tenants;
  v_s public.services;
  v_oh public.opening_hours;
  v_today date;
  v_cur timestamp;
  v_st timestamptz;
  v_en timestamptz;
  v_m record;
begin
  if v_tenant is null then
    return;
  end if;
  select * into v_t from public.tenants where id = v_tenant;
  select * into v_s from public.services where id = p_service_id and tenant_id = v_tenant and active;
  if not found then
    return;
  end if;
  v_today := (now() at time zone v_t.time_zone)::date;
  if p_date < v_today or p_date > v_today + v_t.booking_horizon_days then
    return;
  end if;
  select * into v_oh from public.opening_hours where tenant_id = v_tenant and weekday = extract(dow from p_date);
  if not found then
    return;
  end if;

  v_cur := p_date + v_oh.opens;
  while v_cur + make_interval(mins => v_s.duration_minutes) <= p_date + v_oh.closes loop
    v_st := v_cur at time zone v_t.time_zone;
    v_en := v_st + make_interval(mins => v_s.duration_minutes);
    if v_st >= now() + make_interval(mins => v_t.booking_lead_minutes) then
      for v_m in
        select f.id from public.staff f
        join public.staff_services ss on ss.staff_id = f.id and ss.service_id = v_s.id
        where f.tenant_id = v_tenant and f.active and (p_staff_id is null or f.id = p_staff_id)
        order by f.sort_order, f.id
      loop
        if app.slot_ok(v_tenant, v_m.id, v_st, v_en, null) then
          start := app.to_wall(v_st, v_t.time_zone);
          staff_id := v_m.id;
          return next;
          exit;
        end if;
      end loop;
    end if;
    v_cur := v_cur + make_interval(mins => v_t.slot_step_minutes);
  end loop;
end
$function$

CREATE OR REPLACE FUNCTION public.book_appointment(p_service_id uuid, p_staff_id uuid, p_start text, p_payment text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_tenant uuid := app.current_tenant();
  v_cust uuid := app.my_customer_id();
  v_t public.tenants;
  v_s public.services;
  v_staff uuid;
  v_st timestamptz;
  v_en timestamptz;
  v_hour int;
  v_day int;
  v_id uuid;
begin
  if auth.uid() is null then raise exception 'not_authenticated' using errcode = 'P0001'; end if;
  if v_tenant is null then raise exception 'tenant_unknown' using errcode = 'P0001'; end if;
  if v_cust is null then raise exception 'not_registered' using errcode = 'P0001'; end if;
  if p_payment not in ('in_salon', 'online_demo') then raise exception 'invalid_payment' using errcode = 'P0001'; end if;

  select * into v_t from public.tenants where id = v_tenant;
  select * into v_s from public.services where id = p_service_id and tenant_id = v_tenant and active;
  if not found then raise exception 'not_found' using errcode = 'P0001'; end if;

  -- Rate-Limit je Kundin
  select count(*) filter (where created_at > now() - interval '1 hour'), count(*)
    into v_hour, v_day
    from public.booking_attempts where customer_id = v_cust and created_at > now() - interval '1 day';
  if v_hour >= v_t.max_bookings_per_hour or v_day >= v_t.max_bookings_per_day then
    raise exception 'rate_limited' using errcode = 'P0001';
  end if;

  v_st := app.from_wall(p_start, v_t.time_zone);
  v_en := v_st + make_interval(mins => v_s.duration_minutes);
  if v_st < now() + make_interval(mins => v_t.booking_lead_minutes)
     or v_st > now() + make_interval(days => v_t.booking_horizon_days) then
    raise exception 'slot_taken' using errcode = 'P0001';
  end if;

  if p_staff_id is null then
    select f.id into v_staff
    from public.staff f join public.staff_services ss on ss.staff_id = f.id and ss.service_id = v_s.id
    where f.tenant_id = v_tenant and f.active and app.slot_ok(v_tenant, f.id, v_st, v_en, null)
    order by f.sort_order, f.id limit 1;
    if v_staff is null then raise exception 'slot_taken' using errcode = 'P0001'; end if;
  else
    if not exists (select 1 from public.staff f join public.staff_services ss on ss.staff_id = f.id and ss.service_id = v_s.id
                   where f.id = p_staff_id and f.tenant_id = v_tenant and f.active) then
      raise exception 'not_found' using errcode = 'P0001';
    end if;
    if not app.slot_ok(v_tenant, p_staff_id, v_st, v_en, null) then
      raise exception 'slot_taken' using errcode = 'P0001';
    end if;
    v_staff := p_staff_id;
  end if;

  insert into public.booking_attempts (tenant_id, customer_id) values (v_tenant, v_cust);

  begin
    insert into public.appointments (tenant_id, customer_id, service_id, staff_id, service_name, category_key, staff_name,
                                     starts_at, ends_at, duration_minutes, price_eur, status, payment)
    select v_tenant, v_cust, v_s.id, v_staff, v_s.name, c.key, f.display_name,
           v_st, v_en, v_s.duration_minutes, v_s.price_eur, 'confirmed', p_payment::public.payment_method
    from public.service_categories c, public.staff f
    where c.id = v_s.category_id and f.id = v_staff
    returning id into v_id;
  exception when exclusion_violation then
    -- gleichzeitige Buchung desselben Slots: Postgres hat die zweite abgewiesen
    raise exception 'slot_taken' using errcode = 'P0001';
  end;
  return app.appointment_json(v_id);
end
$function$

CREATE OR REPLACE FUNCTION public.cancel_appointment(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_cust uuid := app.my_customer_id();
  v_a public.appointments;
  v_notice int;
begin
  if v_cust is null then raise exception 'not_found' using errcode = 'P0001'; end if;
  select * into v_a from public.appointments where id = p_id and customer_id = v_cust for update;
  if not found or v_a.status not in ('pending', 'confirmed') then raise exception 'not_found' using errcode = 'P0001'; end if;
  select change_notice_hours into v_notice from public.tenants where id = v_a.tenant_id;
  if v_a.starts_at < now() + make_interval(hours => v_notice) then raise exception 'too_late' using errcode = 'P0001'; end if;
  update public.appointments set status = 'cancelled', updated_at = now() where id = p_id;
  return app.appointment_json(p_id);
end
$function$

CREATE OR REPLACE FUNCTION public.export_my_data()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_id uuid := app.my_customer_id();
  v_c public.customers;
begin
  if v_id is null then raise exception 'not_found' using errcode = 'P0001'; end if;
  select * into v_c from public.customers where id = v_id;
  return jsonb_build_object(
    'exportedAt', now(),
    'profile', app.profile_json(v_c),
    'appointments', coalesce((
      select jsonb_agg(app.appointment_json(a.id) order by a.starts_at)
      from public.appointments a where a.customer_id = v_id), '[]'::jsonb));
end
$function$

CREATE OR REPLACE FUNCTION public.register_customer(p_first_name text, p_last_name text, p_phone text, p_language text, p_marketing boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
  v_tenant uuid := app.current_tenant();
  v_email text := lower(auth.jwt() ->> 'email');
  v_c public.customers;
begin
  if v_uid is null then raise exception 'not_authenticated' using errcode = 'P0001'; end if;
  if v_tenant is null then raise exception 'tenant_unknown' using errcode = 'P0001'; end if;
  if v_email is null then raise exception 'email_missing' using errcode = 'P0001'; end if;

  select * into v_c from public.customers where tenant_id = v_tenant and user_id = v_uid;
  if found then
    if v_c.deletion_requested_at is not null then raise exception 'not_found' using errcode = 'P0001'; end if;
    return app.profile_json(v_c);
  end if;
  if exists (select 1 from public.customers where tenant_id = v_tenant and lower(email) = v_email) then
    raise exception 'email_taken' using errcode = 'P0001';
  end if;

  insert into public.customers (tenant_id, user_id, first_name, last_name, email, phone, language,
                                marketing_consent, marketing_consent_at)
  values (v_tenant, v_uid, trim(p_first_name), trim(p_last_name), v_email, nullif(trim(coalesce(p_phone, '')), ''),
          coalesce(nullif(p_language, ''), 'de'), coalesce(p_marketing, false),
          case when coalesce(p_marketing, false) then now() end)
  returning * into v_c;
  return app.profile_json(v_c);
end
$function$

CREATE OR REPLACE FUNCTION public.reschedule_appointment(p_id uuid, p_new_start text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_cust uuid := app.my_customer_id();
  v_a public.appointments;
  v_t public.tenants;
  v_st timestamptz;
  v_en timestamptz;
begin
  if v_cust is null then raise exception 'not_found' using errcode = 'P0001'; end if;
  select * into v_a from public.appointments where id = p_id and customer_id = v_cust for update;
  if not found or v_a.status not in ('pending', 'confirmed') then raise exception 'not_found' using errcode = 'P0001'; end if;
  select * into v_t from public.tenants where id = v_a.tenant_id;
  if v_a.starts_at < now() + make_interval(hours => v_t.change_notice_hours) then raise exception 'too_late' using errcode = 'P0001'; end if;

  v_st := app.from_wall(p_new_start, v_t.time_zone);
  v_en := v_st + make_interval(mins => v_a.duration_minutes);
  if v_st < now() + make_interval(mins => v_t.booking_lead_minutes)
     or v_st > now() + make_interval(days => v_t.booking_horizon_days)
     or not app.slot_ok(v_t.id, v_a.staff_id, v_st, v_en, v_a.id) then
    raise exception 'slot_taken' using errcode = 'P0001';
  end if;
  begin
    update public.appointments set starts_at = v_st, ends_at = v_en, updated_at = now() where id = p_id;
  exception when exclusion_violation then
    raise exception 'slot_taken' using errcode = 'P0001';
  end;
  return app.appointment_json(p_id);
end
$function$

CREATE OR REPLACE FUNCTION public.rls_auto_enable()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  cmd record;
  tbl name;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        SELECT c.relname INTO tbl FROM pg_catalog.pg_class c WHERE c.oid = cmd.objid;
        EXECUTE format('alter table if exists %I.%I enable row level security', cmd.schema_name, tbl);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.salon_send_chat_message(p_customer_id uuid, p_body text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_tenant uuid := app.current_tenant();
  v_name text;
  v_m public.chat_messages;
begin
  if not app.is_salon_member() then raise exception 'forbidden' using errcode = 'P0001'; end if;
  if not exists (select 1 from public.customers where id = p_customer_id and tenant_id = v_tenant) then
    raise exception 'not_found' using errcode = 'P0001';
  end if;
  select display_name into v_name from public.salon_members where user_id = auth.uid() and tenant_id = v_tenant;
  insert into public.chat_messages (tenant_id, customer_id, sender, sender_name, body)
  values (v_tenant, p_customer_id, 'salon', v_name, btrim(p_body)) returning * into v_m;
  perform app.enqueue_notification(v_tenant, p_customer_id, 'chat', array['push', 'email'],
    jsonb_build_object('title', 'Neue Nachricht von Hello Beauty', 'body', left(v_m.body, 140), 'url', '/app/nachrichten'),
    'chat:' || v_m.id);
  return to_jsonb(v_m);
end
$function$

CREATE OR REPLACE FUNCTION public.send_chat_message(p_body text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_id uuid := app.my_customer_id();
  v_tenant uuid := app.current_tenant();
  v_m public.chat_messages;
begin
  if v_id is null then raise exception 'not_found' using errcode = 'P0001'; end if;
  if (select count(*) from public.chat_messages where customer_id = v_id and sender = 'customer'
      and created_at > now() - interval '10 minutes') >= 20 then
    raise exception 'rate_limited' using errcode = 'P0001';
  end if;
  insert into public.chat_messages (tenant_id, customer_id, sender, body)
  values (v_tenant, v_id, 'customer', btrim(p_body)) returning * into v_m;
  return to_jsonb(v_m);
end
$function$

CREATE OR REPLACE FUNCTION public.set_avatar(p_path text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_id uuid := app.my_customer_id();
begin
  if v_id is null then raise exception 'not_found' using errcode = 'P0001'; end if;
  if p_path is not null and not (p_path like app.current_tenant()::text || '/' || v_id::text || '/%') then
    raise exception 'invalid_path' using errcode = 'P0001';
  end if;
  update public.customers set avatar_path = p_path where id = v_id;
  return jsonb_build_object('avatarPath', p_path);
end
$function$

CREATE OR REPLACE FUNCTION public.set_marketing_consent(p_channel text, p_granted boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_id uuid := app.my_customer_id();
  v_tenant uuid := app.current_tenant();
begin
  if v_id is null then raise exception 'not_found' using errcode = 'P0001'; end if;
  if p_channel not in ('email', 'sms', 'push') then raise exception 'invalid_channel' using errcode = 'P0001'; end if;
  if p_channel = 'email' then
    -- hält die Spalte aus Teil 2 synchron (Trigger schreibt die Historie)
    update public.customers set marketing_consent = p_granted,
      marketing_consent_at = case when p_granted then now() else null end
    where id = v_id and marketing_consent is distinct from p_granted;
    if not found and not exists (select 1 from public.marketing_consents where customer_id = v_id and channel = 'email') then
      insert into public.marketing_consents (tenant_id, customer_id, channel, granted) values (v_tenant, v_id, 'email', p_granted);
    end if;
  else
    insert into public.marketing_consents (tenant_id, customer_id, channel, granted) values (v_tenant, v_id, p_channel, p_granted);
  end if;
  return public.my_consents();
end
$function$

CREATE OR REPLACE FUNCTION public.svc_crm_admit(p_key_id text, p_nonce text, p_limit_per_min integer DEFAULT 120)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_tenant uuid;
  v_hits int;
begin
  select tenant_id into v_tenant from public.crm_bridge_keys where key_id = p_key_id and active;
  if v_tenant is null then raise exception 'unknown_key' using errcode = 'P0001'; end if;
  delete from public.crm_request_nonces where seen_at < now() - interval '10 minutes';
  begin
    insert into public.crm_request_nonces (key_id, nonce) values (p_key_id, p_nonce);
  exception when unique_violation then
    raise exception 'replay' using errcode = 'P0001';
  end;
  insert into public.crm_rate (key_id, window_start, hits) values (p_key_id, date_trunc('minute', now()), 1)
  on conflict (key_id, window_start) do update set hits = public.crm_rate.hits + 1
  returning hits into v_hits;
  delete from public.crm_rate where window_start < now() - interval '1 hour';
  if v_hits > p_limit_per_min then raise exception 'rate_limited' using errcode = 'P0001'; end if;
  return v_tenant;
end
$function$

CREATE OR REPLACE FUNCTION public.svc_crm_chat_send(p_tenant uuid, p_customer uuid, p_body text, p_actor text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_m public.chat_messages;
begin
  if not exists (select 1 from public.customers where id = p_customer and tenant_id = p_tenant) then
    raise exception 'not_found' using errcode = 'P0001';
  end if;
  insert into public.chat_messages (tenant_id, customer_id, sender, sender_name, body)
  values (p_tenant, p_customer, 'salon', left(p_actor, 60), btrim(p_body)) returning * into v_m;
  perform app.enqueue_notification(p_tenant, p_customer, 'chat', array['push', 'email'],
    jsonb_build_object('title', 'Neue Nachricht von Hello Beauty', 'body', left(v_m.body, 140), 'url', '/app/nachrichten'),
    'chat:' || v_m.id);
  perform app.audit(p_tenant, p_actor, 'chat_send', p_customer, null, jsonb_build_object('messageId', v_m.id));
  return to_jsonb(v_m);
end
$function$

CREATE OR REPLACE FUNCTION public.svc_crm_link(p_tenant uuid, p_customer uuid, p_ref text, p_actor text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_l public.crm_links;
begin
  if not exists (select 1 from public.customers where id = p_customer and tenant_id = p_tenant) then
    raise exception 'not_found' using errcode = 'P0001';
  end if;
  if exists (select 1 from public.crm_links where customer_id = p_customer and status = 'linked') then
    raise exception 'already_linked' using errcode = 'P0001';
  end if;
  if exists (select 1 from public.crm_links where tenant_id = p_tenant and crm_customer_ref = p_ref and status = 'linked') then
    raise exception 'ref_in_use' using errcode = 'P0001';
  end if;
  insert into public.crm_links (tenant_id, customer_id, crm_customer_ref, linked_by)
  values (p_tenant, p_customer, p_ref, p_actor) returning * into v_l;
  perform app.audit(p_tenant, p_actor, 'link', p_customer, p_ref, '{}');
  return to_jsonb(v_l);
end
$function$

CREATE OR REPLACE FUNCTION public.svc_crm_unlink(p_tenant uuid, p_customer uuid, p_actor text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_l public.crm_links;
begin
  update public.crm_links set status = 'unlinked', unlinked_by = p_actor, unlinked_at = now()
  where customer_id = p_customer and tenant_id = p_tenant and status = 'linked' returning * into v_l;
  if v_l.id is null then raise exception 'not_linked' using errcode = 'P0001'; end if;
  perform app.audit(p_tenant, p_actor, 'unlink', p_customer, v_l.crm_customer_ref, '{}');
  return to_jsonb(v_l);
end
$function$

CREATE OR REPLACE FUNCTION public.update_profile(p_patch jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_id uuid := app.my_customer_id();
  v_c public.customers;
  v_phone text;
  v_marketing boolean;
begin
  if v_id is null then raise exception 'not_found' using errcode = 'P0001'; end if;
  select * into v_c from public.customers where id = v_id;

  v_phone := case when p_patch ? 'phone' then nullif(trim(coalesce(p_patch ->> 'phone', '')), '') else v_c.phone end;
  v_marketing := coalesce((p_patch ->> 'marketingConsent')::boolean, v_c.marketing_consent);

  update public.customers set
    first_name = coalesce(nullif(trim(p_patch ->> 'firstName'), ''), first_name),
    last_name = coalesce(nullif(trim(p_patch ->> 'lastName'), ''), last_name),
    phone = v_phone,
    language = coalesce(p_patch ->> 'language', language),
    notify_email = coalesce((p_patch ->> 'notifyEmail')::boolean, notify_email),
    notify_sms = case when v_phone is null then false else coalesce((p_patch ->> 'notifySms')::boolean, notify_sms) end,
    marketing_consent = v_marketing,
    marketing_consent_at = case
      when v_marketing = marketing_consent then marketing_consent_at
      when v_marketing then now()
      else null end
  where id = v_id
  returning * into v_c;
  return app.profile_json(v_c);
end
$function$
